-- case: spanset_or
-- q: { resource.service.name = "frontend" } || { span.http.response.status_code >= 500 } limit=20 spss=3
WITH (SELECT (groupArray(trace_id), groupArray(keys))
      FROM (SELECT trace_id, maxIf(start_ns, s0) AS last, groupUniqArray(intDiv(start_ns, 300000000000)) AS keys
FROM (SELECT *, (f1 OR f2) AS s0
FROM (SELECT *, max(f1) OVER (PARTITION BY trace_id) AS c1, max(f2) OVER (PARTITION BY trace_id) AS c2
FROM (SELECT trace_id, span_id, start_ns, duration_ns, f1, f2
FROM (SELECT *, (((service_type = 'string' AND service = 'frontend') OR (NOT service_type = 'string' AND resource_id IN (SELECT resource_id FROM resources WHERE day >= toDate(fromUnixTimestamp64Nano(1790084801000000000), 'UTC') AND day <= toDate(fromUnixTimestamp64Nano(1790095600999999999), 'UTC') AND ((coalesce(attrs.`service%2Ename`.:String = 'frontend', false) OR has(attrs.`service%2Ename`.:`Array(Nullable(String))`, 'frontend'))))))) AS f1, ((coalesce(attrs.`http%2Eresponse%2Estatus_code`.:Int64 >= 500, false) OR coalesce(attrs.`http%2Eresponse%2Estatus_code`.:Float64 >= 500, false) OR arrayExists(ae -> coalesce(ae >= 500, false), attrs.`http%2Eresponse%2Estatus_code`.:`Array(Nullable(Int64))`) OR arrayExists(ae -> coalesce(ae >= 500, false), attrs.`http%2Eresponse%2Estatus_code`.:`Array(Nullable(Float64))`))) AS f2 FROM spans
WHERE start_ns >= 1790084801000000000 AND start_ns < 1790095601000000000
  AND intDiv(start_ns, 300000000000) BETWEEN intDiv(1790084801000000000, 300000000000) AND intDiv(1790095600999999999, 300000000000)
  AND toDate(fromUnixTimestamp64Nano(start_ns), 'UTC') >= toDate('2026-09-22') AND toDate(fromUnixTimestamp64Nano(start_ns), 'UTC') <= toDate('2026-09-22')
  AND ((((service_type = 'string' AND service = 'frontend') OR (NOT service_type = 'string' AND resource_id IN (SELECT resource_id FROM resources WHERE day >= toDate(fromUnixTimestamp64Nano(1790084801000000000), 'UTC') AND day <= toDate(fromUnixTimestamp64Nano(1790095600999999999), 'UTC') AND ((coalesce(attrs.`service%2Ename`.:String = 'frontend', false) OR has(attrs.`service%2Ename`.:`Array(Nullable(String))`, 'frontend'))))))) OR ((coalesce(attrs.`http%2Eresponse%2Estatus_code`.:Int64 >= 500, false) OR coalesce(attrs.`http%2Eresponse%2Estatus_code`.:Float64 >= 500, false) OR arrayExists(ae -> coalesce(ae >= 500, false), attrs.`http%2Eresponse%2Estatus_code`.:`Array(Nullable(Int64))`) OR arrayExists(ae -> coalesce(ae >= 500, false), attrs.`http%2Eresponse%2Estatus_code`.:`Array(Nullable(Float64))`))))
LIMIT 1 BY trace_id, start_ns, span_id, kind))))
GROUP BY trace_id
HAVING countIf(s0) > 0
ORDER BY last DESC, trace_id ASC
LIMIT 20)) AS top
